window.LUMINA = {"generated":"2026-11-07","topics":[{"id":"dermatologie","label":"Dermatologie","short":"Dermatologie","color":null,"description":"Photobiomodulation en dermatologie : plaies et ulcères, cicatrices et brûlures, radiodermite, alopécie, acné et dermatoses inflammatoires, vieillissement cutané, infections et pigmentation.","cadence":"hebdomadaire","since":"2000-01-01","status":"actif","hero":"la dermatologie","exclusions_note":"photothérapie dynamique, lasers ablatifs ou vasculaires, épilation, études sans rapport avec la peau…","subgroups":["plaies","cicatrices","radiodermite","alopécie","inflammatoire","esthétique","infections","pigmentation"],"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"low-intensity laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"PBMT\"[tiab] OR \"light-emitting diode\"[tiab] OR \"laser acupuncture\"[tiab] OR \"high-intensity laser\"[tiab]) AND (\"skin\"[tiab] OR \"cutaneous\"[tiab] OR \"wound*\"[tiab] OR \"dermatitis\"[tiab] OR \"radiodermatitis\"[tiab] OR \"acne\"[tiab] OR \"alopecia\"[tiab] OR \"hair loss\"[tiab] OR \"psoriasis\"[tiab] OR \"scar*\"[tiab] OR \"keloid*\"[tiab] OR \"ulcer*\"[tiab] OR \"burn*\"[tiab] OR \"vitiligo\"[tiab] OR \"herpes\"[tiab] OR \"rosacea\"[tiab] OR \"photoaging\"[tiab] OR \"wrinkle*\"[tiab] OR \"Skin Diseases\"[MeSH]) NOT (\"photodynamic\"[ti] OR \"hair removal\"[ti] OR \"epilation\"[ti])","n_raw":5234,"n_excluded":0,"n":5234,"n_curated":0,"file":"assets/topics/dermatologie.js?v=4411b5720b","years":[2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026]},{"id":"gynecologie","label":"Gynécologie","short":"Gynécologie","color":"#c2185b","description":"Photobiomodulation en gynécologie et obstétrique : sécheresse et atrophie vulvovaginale (syndrome génito-urinaire de la ménopause), effets secondaires après cancer gynécologique ou mammaire, douleurs vulvaires et pelviennes, périnée et allaitement, fertilité.","cadence":"hebdomadaire","since":"2000-01-01","status":"actif","hero":"la gynécologie","exclusions_note":"lasers vaginaux ablatifs CO2 et Er:YAG (ce n'est pas de la photobiomodulation), lymphœdème du membre supérieur, études animales sans rapport gynécologique…","subgroups":["GSM","onco","vulve","pelvien","obstétrique","fertilité"],"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"low-intensity laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"PBMT\"[tiab] OR \"light-emitting diode\"[tiab] OR \"laser acupuncture\"[tiab]) AND (\"vagina*\"[tiab] OR \"vulva*\"[tiab] OR \"vulvodynia\"[tiab] OR \"dyspareunia\"[tiab] OR \"genitourinary syndrome\"[tiab] OR \"menopaus*\"[tiab] OR \"lichen sclerosus\"[tiab] OR \"gynecolog*\"[tiab] OR \"gynaecolog*\"[tiab] OR \"cervical cancer\"[tiab] OR \"endometrial cancer\"[tiab] OR \"ovar*\"[tiab] OR \"uterine\"[tiab] OR \"dysmenorrh*\"[tiab] OR \"endometriosis\"[tiab] OR \"pelvic pain\"[tiab] OR \"perine*\"[tiab] OR \"episiotomy\"[tiab] OR \"nipple\"[tiab] OR \"breastfeeding\"[tiab] OR \"polycystic ovary\"[tiab] OR \"infertil*\"[tiab] OR \"urinary incontinence\"[tiab] OR \"Genital Diseases, Female\"[MeSH])","n_raw":399,"n_excluded":121,"n":278,"n_curated":116,"file":"assets/topics/gynecologie.js?v=c68dc4a919","years":[2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026]},{"id":"mucite-orale","label":"Mucite buccale","short":"Mucite","color":"#d9480f","description":"Prévention et traitement des mucites induites par la chimiothérapie, la radiothérapie ou la greffe de cellules souches hématopoïétiques par photobiomodulation (PBM / LLLT).","cadence":"hebdomadaire","since":"2000-01-01","status":"actif","hero":"la mucite","exclusions_note":"aphtes récurrents, stomatites prothétiques, péri-implantite, laser haute intensité en rhumatologie…","subgroups":null,"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"laser therapy\"[tiab] OR \"PBMT\"[tiab]) AND (\"mucositis\"[tiab] OR \"Stomatitis\"[MeSH] OR \"Mucositis\"[MeSH]) NOT (\"peri-implant\"[tiab] OR \"periimplant\"[tiab] OR \"peri-implantitis\"[tiab])","n_raw":523,"n_excluded":60,"n":463,"n_curated":198,"file":"assets/topics/mucite-orale.js?v=a86a8b5445","years":[2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026]},{"id":"musculo-squelettique","label":"Musculo-squelettique","short":"Musculo-squelettique","color":null,"description":"Photobiomodulation et laser haute intensité dans les pathologies de l'appareil locomoteur : tendinopathies, arthrose, rachis, ATM, fibromyalgie, épaule, os et fractures, muscle et sport.","cadence":"hebdomadaire","since":"2000-01-01","status":"actif","hero":"l'appareil locomoteur","exclusions_note":"études hors appareil locomoteur, lasers chirurgicaux ou ablatifs, photothérapie dynamique…","subgroups":["tendon","arthrose","rachis","ATM","fibro","épaule","os","muscle"],"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"low-intensity laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"PBMT\"[tiab] OR \"light-emitting diode\"[tiab] OR \"laser acupuncture\"[tiab] OR \"high-intensity laser\"[tiab]) AND (\"musculoskeletal\"[tiab] OR \"tendin*\"[tiab] OR \"tendon*\"[tiab] OR \"osteoarthritis\"[tiab] OR \"arthritis\"[tiab] OR \"low back pain\"[tiab] OR \"neck pain\"[tiab] OR \"radiculopathy\"[tiab] OR \"temporomandibular\"[tiab] OR \"fibromyalgia\"[tiab] OR \"myofascial\"[tiab] OR \"shoulder\"[tiab] OR \"knee\"[tiab] OR \"epicondyl*\"[tiab] OR \"plantar fasci*\"[tiab] OR \"fracture*\"[tiab] OR \"bone\"[tiab] OR \"muscle*\"[tiab] OR \"Musculoskeletal Diseases\"[MeSH]) NOT (\"photodynamic\"[ti])","n_raw":3616,"n_excluded":0,"n":3616,"n_curated":0,"file":"assets/topics/musculo-squelettique.js?v=48bd9d488d","years":[2000,2001,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026]},{"id":"neuropathie-peripherique","label":"Neuropathies périphériques","short":"Neuropathies","color":"#2a78d6","description":"Prévention et traitement des neuropathies périphériques par photobiomodulation : neuropathie induite par la chimiothérapie (CIPN), neuropathie diabétique et autres atteintes nerveuses périphériques.","cadence":"hebdomadaire","since":"2000-01-01","status":"actif","hero":"les neuropathies périphériques","exclusions_note":"ulcères du pied diabétique, glaucome, lésions de la moelle épinière, radiculopathies (réservées au futur thème musculo-squelettique)…","subgroups":null,"pubmed_query":"(\"photobiomodulation\"[tiab] OR \"low-level laser\"[tiab] OR \"low level laser\"[tiab] OR \"LLLT\"[tiab] OR \"low-level light\"[tiab] OR \"Low-Level Light Therapy\"[MeSH] OR \"PBMT\"[tiab] OR \"laser therapy\"[tiab] OR \"light-emitting diode\"[tiab] OR \"high-intensity laser\"[tiab]) AND (\"peripheral neuropathy\"[tiab] OR \"polyneuropathy\"[tiab] OR \"Peripheral Nervous System Diseases\"[MeSH] OR \"neuropathic\"[tiab] OR \"neuropathy\"[tiab] OR \"CIPN\"[tiab]) NOT (\"trigeminal\"[ti] OR \"burning mouth\"[ti])","n_raw":381,"n_excluded":65,"n":317,"n_curated":120,"file":"assets/topics/neuropathie-peripherique.js?v=b257f53efa","years":[2000,2002,2003,2004,2005,2006,2007,2008,2009,2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026]}],"syntheses":{"dermatologie":{},"gynecologie":{"years":{"2020–2023":{"headline":"Les débuts : douleurs pelviennes, dysménorrhée et premières recommandations","l1":"De 2020 à 2023, la PBM en gynécologie se développe surtout dans la douleur pelvienne chronique (PBM transvaginale), la dysménorrhée et l'urogynécologie. Les recommandations françaises (CNGOF 2021) jugent les preuves insuffisantes, et une première cohorte française après cancer est encourageante.","l2":"Les essais randomisés de cette période donnent des résultats contrastés. Dans la douleur myofasciale pelvienne, la PBM 808 nm n'ajoute rien aux étirements vaginaux (103 femmes, double aveugle). Dans la dysménorrhée, la LED sur points d'acupuncture soulage presque autant que la pilule (156 femmes). En urogynécologie, un patch lumineux de phase III réduit les fuites par urgence, et des essais plus petits améliorent l'incontinence d'effort en complément de la rééducation.\n\nEn obstétrique, une séance unique de laser ne soulage pas plus les mamelons qu'un placebo (80 femmes). La PBM transvaginale montre de bons résultats en cohortes (douleur pelvienne chronique, cystite interstitielle), sans groupe témoin. Après cancer, la cohorte du CHU de Nîmes (Bulletin du Cancer 2023) rapporte 72 % de patientes améliorées. Les recommandations CNGOF/GEMVi de 2021 ne recommandent pas les lasers ablatifs en première ligne et jugent les données sur la PBM trop faibles.","l3":[{"h":"Douleurs pelviennes","p":"PBM transvaginale : cohortes de 13, 128 et 140 femmes, avec 60 à 65 % de répondeuses. Mais l'essai contre simulation dans la douleur myofasciale (103 femmes) ne montre aucun bénéfice ajouté aux étirements. Dosimétrie chez la brebis : seulement 3 % de l'irradiance atteint le muscle releveur, ce qui pourrait expliquer les échecs à faible puissance."},{"h":"Dysménorrhée","p":"LED sur points CV4 et CV6 contre pilule (156 femmes) : 73,6 % contre 85,7 % de répondeuses (NS), pilule plus antalgique. Laser haute intensité équivalent au basse énergie (30 femmes)."},{"h":"Urogynécologie","p":"Patch LED de phase III dans l'hyperactivité vésicale : fuites par urgence −1,0 contre −0,4 par jour. Laser-acupuncture dans l'hyperactivité vésicale et PBM + rééducation dans l'incontinence d'effort : petits essais favorables."},{"h":"Après cancer et recommandations","p":"CNGOF/GEMVi 2021 : lasers ablatifs non recommandés en première ligne (grade C), PBM insuffisamment évaluée. Cohorte de Nîmes (28 patientes) : 72 % améliorées. Deux cas de sténose vaginale post-radique traités par LED bleue."},{"h":"Fertilité (préclinique)","p":"Protection ovarienne contre le cyclophosphamide chez la souris, synéchies utérines, SOPK chez le rat : une base mécanistique pour l'oncofertilité."}]},"2024":{"headline":"Lichen scléreux, candidose et premiers protocoles randomisés","l1":"En 2024, de nouvelles indications vulvaires apparaissent : le lichen scléreux (100 femmes en complément des corticoïdes) et la candidose récidivante (LED bleue). Deux protocoles d'essais randomisés sont lancés dans le syndrome génito-urinaire de la ménopause, et l'ACOG rappelle la faiblesse des preuves.","l2":"Vulve : une cohorte danoise de 100 femmes avec lichen scléreux réfractaire améliore sa qualité de vie avec un laser 808 nm, et un laser bleu réduit prurit et fissures chez 12 patientes. Dans la candidose récidivante, un essai randomisé de 60 femmes montre que deux séances de LED bleue ajoutées à l'antifongique réduisent nettement la charge en Candida.\n\nMénopause : un laser diode non ablatif améliore sécheresse et dyspareunie à 6 mois (22 femmes), et deux protocoles d'essais contre placebo sont publiés ; leurs résultats sortiront en 2026. En obstétrique, la PBM fait mieux que la cryothérapie sur la douleur périnéale (56 femmes) et qu'une crème sur les crevasses (50 femmes), mais la méta-analyse sur les mamelons reste incertaine. La série d'experts de l'ACOG distingue clairement lasers ablatifs et PBM et ne retient pas de preuve forte pour la douleur pelvienne.","l3":[{"h":"Vulve et infections","p":"Lichen scléreux : 100 femmes, 10 séances de 808 nm, 7 domaines de qualité de vie sur 8 améliorés. Candidose : DM de 8,27 sur la charge en Candida avec LED bleue + antifongique."},{"h":"Ménopause","p":"Laser diode non ablatif : VHI 12 → 19,3, sécheresse 7,7 → 3,7. Protocoles PBM vulvaire 808 nm et PBM + rééducation."},{"h":"Obstétrique","p":"PBM supérieure à la cryothérapie (douleur à 24 h, p < 0,001). Crevasses : PBM supérieure à une crème anti-inflammatoire. Méta-analyse des mamelons : PBM contre placebo DM −0,15, incertain."},{"h":"Dysménorrhée et fertilité","p":"Chez l'animal, le rouge 630 nm pulsé est le plus efficace contre la dysménorrhée. Vieillissement ovarien amélioré chez la souris ; trois grossesses après PBM dans une série de cas d'infertilité inexpliquée."}]},"2025":{"headline":"Méta-analyses : favorable sur la dysménorrhée et l'allaitement, neutre sur le périnée","l1":"En 2025, les méta-analyses tranchent : la PBM réduit la douleur de la dysménorrhée (−4 points contre simulation) et la douleur des crevasses (OR 0,43), mais pas la douleur périnéale après accouchement. Un premier essai contre simulation est positif dans la vestibulodynie.","l2":"Dysménorrhée : la méta-analyse de 12 essais (645 femmes) montre une baisse de la douleur de 4 points à 12 semaines contre simulation. Allaitement : la méta-analyse de 7 essais est favorable (OR 0,43 sur la douleur de succion), alors qu'une autre plus ancienne, à 3 essais, ne l'était pas. Périnée : l'infrarouge aide un peu, mais pas le laser basse énergie (13 études), et une séance unique de PBM ne bat pas la simulation (60 femmes).\n\nVulve : l'essai canadien dans la vestibulodynie provoquée (30 femmes, 15 séances) réduit la douleur avec des tailles d'effet de 0,6 à 0,9, sans gain sur la sexualité. La lumière bleue soulage 79 % des candidoses récidivantes résistantes aux azolés. Ménopause : en France, la première étude chez l'humain de la sonde MILTA GYNECO montre une bonne tolérance et une dyspareunie réduite de moitié. En sénologie, la lumière bleue aide à cicatriser les plaies compliquées de reconstruction mammaire.","l3":[{"h":"Dysménorrhée","p":"Méta-analyse : DM −4,02 contre simulation à 12 semaines ; avantage contre la pilule. Laser-acupuncture équivalente à l'électroacupuncture (114 femmes)."},{"h":"Obstétrique","p":"Mamelons : OR 0,43 (7 ECR, certitude faible). Périnée : laser contre placebo DMS −0,31 (NS) ; séance unique non supérieure. Une séance ne suffit pas, et la dose semble déterminante."},{"h":"Vulve","p":"Vestibulodynie : premier ECR contre simulation positif sur la douleur. Candidose : 79 % d'amélioration immédiate, 58 % à 6 mois (62 femmes résistantes)."},{"h":"Ménopause et urogynécologie","p":"Sonde MILTA GYNECO : 146 événements mineurs sur 148, VHI 12,7 → 17,6, dyspareunie 7,7 → 3,9. Laser basse énergie dans l'incontinence d'effort et le syndrome génito-urinaire : cohorte de 41 femmes favorable."},{"h":"Après cancer et sénologie","p":"Lumière bleue sur plaies de reconstruction mammaire (27 patientes, 5 séances médianes). Infection de prothèse traitée par pression négative + PBM."}]},"2026":{"headline":"Les essais contre placebo arrivent dans la ménopause et après cancer du sein","l1":"En 2026, deux essais contre placebo montrent que la PBM intravaginale améliore l'incontinence et la sécheresse de la ménopause. Une étude brésilienne fait passer la douleur vaginale de 9,5 à 1/10 chez des femmes sous hormonothérapie pour cancer du sein. Sur le périnée post-partum, en revanche, les méta-analyses restent négatives.","l2":"Syndrome génito-urinaire : l'essai en double aveugle contre placebo (808 nm, 4 séances) réduit les fuites urinaires et la sécheresse ; un deuxième essai montre qu'ajoutée à la rééducation, la PBM améliore la sexualité (FSFI +4,6) et l'incontinence. Une étude taïwanaise (660 nm par sonde) ramène toutes les patientes au-dessus du seuil d'atrophie. Après cancer : la PBM LED bleu + rouge soulage presque complètement la douleur vaginale sous inhibiteurs de l'aromatase (24 femmes, groupe d'observation non traité).\n\nVulvodynie : la méta-analyse en réseau de 34 essais classe les thérapies tissulaires, PBM comprise, en tête contre placebo ; une cohorte française ne trouve que 52 % de succès. Obstétrique : quatre méta-analyses et un essai en double aveugle ne trouvent pas de bénéfice du laser sur la douleur périnéale, alors qu'un essai sur les mamelons est positif. La consultation internationale de médecine sexuelle (ICSM) juge les preuves encore insuffisantes pour recommander la PBM.","l3":[{"h":"Ménopause","p":"Essai contre placebo 808 nm : fuites et ICIQ-SF améliorés, sexualité inchangée. PBM + rééducation : FSFI DM 4,55, ICIQ-SF −3,06. Étude 660 nm : 100 % au-dessus du seuil non atrophique à 3 mois, mais seulement 13 % retrouvent une fonction sexuelle normale."},{"h":"Après cancer","p":"Cancer du sein sous hormonothérapie : EVA 9,46 → 1,04, QS-F 23 → 87. Rappel radique après cisplatine dans un cancer du col : amélioration en une semaine avec une PBM multi-longueurs d'onde."},{"h":"Vulve","p":"Méta-analyse en réseau vulvodynie : thérapies tissulaires POMP −16 contre placebo (confiance modérée), en tête du classement. LED 415 nm efficace dans un modèle de vaginose bactérienne."},{"h":"Obstétrique","p":"Périnée : 4 méta-analyses (LLLT contre placebo DM 0,03 ; DMS 0,04 ; DMS −0,16) et un ECR à 660 nm sans bénéfice, mais moins d'antalgiques ; une cohorte portugaise (808 nm, lésions de grade 2–3) est positive. Mamelons : ECR multicentrique positif dès 30 minutes."},{"h":"Fertilité","p":"Ovocytes humains immatures : maturation deux fois plus rapide sous 810 nm, sans stress oxydatif. LED portable 630 nm : compte de follicules antraux 2 → 6 dans un pilote."}]},"2000–2019":{"headline":"Vingt ans de pionniers : obstétrique, dysménorrhée et premiers essais vulvaires","l1":"Avant 2020, la PBM en gynécologie reste marginale : une vingtaine d'études, surtout en obstétrique (mamelons, épisiotomie), dans la dysménorrhée et, à la fin de la période, dans la vulve (vestibulodynie, lichen scléreux). Les patchs lumineux contre la dysménorrhée et le laser contre les crevasses sont positifs ; le laser après épisiotomie ne l'est pas.","l2":"En obstétrique, le laser après épisiotomie échoue dans trois essais (52, 114 et 54 femmes), alors que la LED et le laser 660 nm soulagent les lésions et la douleur des mamelons (8 et 59 femmes). Le laser sur la cicatrice de césarienne ne perturbe pas l'allaitement. La laser-acupuncture ne réduit ni les bouffées de chaleur (40 femmes) ni la dysménorrhée (48 femmes), mais un patch lumineux adhésif est efficace dans deux essais coréens (31 puis 88 femmes, −4,3 contre −1,8 points).\n\nÀ la fin de la décennie apparaissent les premiers essais vulvaires et pelviens : vestibulodynie (78 % contre 44 % d'amélioration, critère principal seulement), lichen scléreux (Nd:YAG non ablatif > dermocorticoïdes), endométriose (laser haute intensité pulsé, douleur et qualité de vie). Trois protocoles brésiliens annoncent les essais de la décennie suivante.","l3":[{"h":"Obstétrique","p":"Épisiotomie : trois essais négatifs (doses faibles, 0,45 J par séance dans l'un). Mamelons : LED (8 séances) et laser 660 nm (−2 points à 24 h) favorables. Césarienne : prolactine et allaitement préservés."},{"h":"Dysménorrhée et ménopause","p":"Patch lumineux sur acupoints : 83 % de soulagement (pilote), puis −4,3 contre −1,8 points (88 femmes, multicentrique). Laser-acupuncture : négative dans la dysménorrhée et les bouffées de chaleur."},{"h":"Vulve et pelvis","p":"Vestibulodynie (34 femmes) : amélioration chez 78 % contre 44 %. Lichen scléreux : Nd:YAG non ablatif > corticoïdes jusqu'à 6 mois (40 femmes). Endométriose : laser haute intensité pulsé, douleur et adhérences réduites (40 femmes)."}]}},"global":{"headline":"2020 → 2026 : ce que la PBM apporte, ou non, en gynécologie","l1":"Sur sept ans, la PBM gynécologique se précise. Elle est la mieux étayée dans la dysménorrhée, les crevasses de l'allaitement, la sécheresse et l'incontinence de la ménopause, et dans la vulvodynie. Elle ne fait pas ses preuves sur la douleur périnéale après accouchement. Après cancer, les résultats sont spectaculaires mais encore non randomisés.","l2":"Ce qui se confirme : dysménorrhée (méta-analyse 2025, −4 points contre simulation), crevasses (méta-analyse 2025, OR 0,43 ; essai 2026 positif), syndrome génito-urinaire de la ménopause (deux essais contre placebo en 2026, effet net sur l'incontinence et la sécheresse), vulvodynie (essai contre simulation 2025, méta-analyse en réseau 2026). Ce qui ne se confirme pas : la douleur périnéale post-partum (quatre méta-analyses négatives), et l'ajout de la PBM aux étirements dans la douleur myofasciale pelvienne.\n\nCe qui est prometteur : la sécheresse et la douleur vaginale après cancer (cohorte de Nîmes 2023, cancer du sein sous hormonothérapie 2026), la candidose récidivante (LED bleue) et le lichen scléreux réfractaire. En fertilité, tout reste préclinique ou pilote. Les recommandations (CNGOF 2021, ICSM 2024/2026) restent prudentes : la PBM est une option complémentaire, sans indication validée en première ligne.","l3":[{"h":"0. Avant 2020 : les pionniers","p":"De 2000 à 2019, une vingtaine d'études seulement, surtout en obstétrique et dans la dysménorrhée. On y trouve déjà les deux tendances qui se confirment ensuite : la PBM soulage les mamelons de l'allaitante et la dysménorrhée (patchs lumineux), mais pas la douleur après épisiotomie."},{"h":"1. Une différence essentielle : PBM et lasers ablatifs","p":"Les lasers vaginaux CO2 et Er:YAG (ablatifs, thermiques) dominent la littérature et ne sont pas de la PBM ; ils sont exclus de ce thème. Les recommandations françaises et l'ACOG les évaluent séparément. La PBM utilise des puissances faibles (rouge, proche infrarouge, bleu) sans destruction tissulaire."},{"h":"2. Sécheresse et ménopause : le sous-groupe qui progresse le plus","p":"Il n'y avait que des protocoles en 2024. En 2026, deux essais contre placebo positifs sur l'incontinence et les symptômes vaginaux, et une étude à 660 nm avec normalisation de l'index de santé vaginale. La fonction sexuelle reste le critère le moins amélioré."},{"h":"3. Après cancer : un besoin fort, des preuves en construction","p":"Les œstrogènes locaux sont souvent évités après cancer du sein. La PBM y montre des résultats spectaculaires (douleur 9,5 → 1/10), mais dans des études non randomisées. Un essai contre placebo est la priorité. Les données in vitro sur cellules de cancer gynécologique sont plutôt rassurantes, mais limitées."},{"h":"4. Obstétrique : allaitement oui, périnée non","p":"Sur les crevasses, les essais à plusieurs séances sont positifs, alors qu'une séance unique ne suffit pas. Sur le périnée, la convergence des méta-analyses de 2025–2026 est négative ; la cryothérapie reste le premier choix. Pendant la grossesse, faute de données, la PBM abdominopelvienne est à éviter hors protocole."},{"h":"5. Vulve et douleurs pelviennes","p":"Vulvodynie : premier essai contre simulation positif (2025) et méta-analyse en réseau favorable (2026), avec environ une répondeuse sur deux en pratique. Dysménorrhée : méta-analyse favorable ; la LED est presque aussi efficace que la pilule, sans hormones. Candidose récidivante : la LED bleue 415 nm est un adjuvant prometteur."}],"table":{"cols":["2000–2019","2020–2023","2024","2025","2026"],"rows":[{"label":"Sécheresse / ménopause","cells":["Laser-acupuncture : bouffées de chaleur, négatif","Incontinence : petits ECR ; patch phase III (hyperactivité vésicale)","Diode non ablatif ; 2 protocoles ECR","Sonde MILTA (France) : tolérance","2 ECR contre placebo positifs"]},{"label":"Après cancer","cells":["—","Cohorte Nîmes : 72 % améliorées","—","Plaies de reconstruction mammaire","Cancer du sein : douleur 9,5 → 1/10"]},{"label":"Vulve & vagin","cells":["Vestibulodynie (pilote) ; lichen Nd:YAG > corticoïdes","Revue lasers vulvodynie","Lichen scléreux (100) ; candidose ECR","Vestibulodynie : ECR positif","Méta-analyse en réseau vulvodynie"]},{"label":"Douleurs pelviennes","cells":["Patch dysménorrhée : 2 ECR positifs ; endométriose","PBM transvaginale (cohortes) ; ECR myofascial négatif","Dysménorrhée (préclinique)","Méta-analyse dysménorrhée : −4 points","Protocoles stérilet, acupoints"]},{"label":"Obstétrique","cells":["Épisiotomie : 3 ECR négatifs ; mamelons positifs","Mamelons : séance unique négative","PBM > cryothérapie (périnée)","Mamelons : OR 0,43 ; périnée négatif","Périnée : 4 méta-analyses négatives ; mamelons ECR +"]},{"label":"Recommandations","cells":["—","CNGOF 2021 : preuves insuffisantes","ACOG : pas de preuve forte","—","ICSM : pas de consensus"]}]}}},"mucite-orale":{"years":{"2024":{"headline":"L'année du bilan : un effet constant, des preuves fragiles","l1":"En 2024, les méta-analyses confirment que la PBM réduit d'environ moitié la mucite sévère en ORL, mais une revue parapluie montre que les revues sont de faible qualité, et une méta-analyse pédiatrique est négative.","l2":"La méta-analyse de Head & Neck (14 essais, 869 patients ORL) chiffre l'effet : mucite sévère réduite de 55 % en fin de traitement (RR 0,45), douleur diminuée d'environ 1 point, meilleurs résultats à faible puissance (10–25 mW). La revue parapluie de BMC Oral Health tempère ce résultat : 71 % des revues sont de qualité critiquement faible et une seule estimation est « fortement suggestive ». En pédiatrie, la méta-analyse d'In Vivo ne trouve pas d'effet préventif (RR 0,99). Cochrane publie le protocole d'une revue dédiée.\n\nSur le terrain, les études montrent l'importance du moment et de la fréquence : la PBM préventive dès le conditionnement fait mieux que la curative dans le myélome, la PBM quotidienne fait mieux qu'un jour sur trois. Les programmes pédiatriques de greffe (infirmière dédiée, Children's Oncology Group) prouvent la faisabilité et réduisent les coûts. Côté sécurité, deux signaux précliniques (mélanome à 808 nm, cellules de cancer buccal) et la synthèse du Bulletin du Cancer rappellent de respecter les doses et d'informer le patient.","l3":[{"h":"Efficacité","p":"Méta-analyse ORL de référence : RR 0,45 (0,24–0,85) pour la mucite sévère en fin de traitement ; effet dès la 2e semaine sur l'incidence. La méta-analyse des interventions non médicamenteuses (27 essais) va dans le même sens (RR 0,54 toutes interventions confondues). En revanche, chez l'enfant, la méta-analyse In Vivo (5 essais poolés) ne montre pas d'effet ; l'essai égyptien en LAM (42 enfants, double aveugle) est, lui, nettement positif."},{"h":"Qualité des preuves","p":"La revue parapluie (21 revues, 40 méta-analyses) est le fait marquant méthodologique : l'effet est constant mais repose sur des synthèses de qualité critiquement faible. Le protocole Cochrane annonce la revue qui devrait servir de référence."},{"h":"Protocole et organisation","p":"Préventif plutôt que curatif (myélome, p < 0,0001), quotidien plutôt qu'espacé (cancer buccal), puissance faible (10–25 mW). La greffe pédiatrique montre qu'une infirmière dédiée rend le programme durable, avec moins de nutrition parentérale (18 % contre 61 %) et des coûts réduits. La revue médico-économique (GRADE modéré) conclut à un bon rapport coût-efficacité à moyen terme."},{"h":"Douleur","p":"La PBM haute puissance soulage immédiatement la mucite réfractaire (94 % des séances), et le concept de PBM « préemptive » se développe. Un débat par lettres accompagne ces travaux (Oral Diseases, Int J Paediatr Dent)."},{"h":"Sécurité oncologique","p":"Signal préclinique à 808 nm sur le mélanome murin ; effets dépendants de la puissance sur les cellules de carcinome buccal ; revue de Frontiers in Oncology aux résultats discordants. Cliniquement, la cohorte brésilienne de 751 patients ne montre pas de surmortalité (le gain de survie apparent est probablement un biais). La synthèse francophone du Bulletin du Cancer fixe le cadre : doses validées, information et consentement en zone tumorale."}]},"2025":{"headline":"L'année du « comment » : voie extrabuccale, LED, domicile","l1":"En 2025, la question n'est plus de savoir si la PBM marche mais comment la délivrer : la voie extrabuccale égale l'intrabuccale en ORL, l'ajouter sur les glandes salivaires apporte un bénéfice, et les dispositifs automatiques ou à domicile apparaissent.","l2":"L'essai multicentrique brésilien (58 patients ORL) montre une efficacité équivalente de la PBM extrabuccale (810/980 nm) et intrabuccale (660 nm), avec une déglutition et un goût mieux préservés. Un autre essai (75 patients) montre que l'association des deux voies améliore mucite, débit salivaire et qualité de vie. Les dispositifs se diversifient : gouttière laser à trois longueurs d'onde, appareil à domicile auto-administré, LED (revue GRADE faible mais favorable).\n\nLes synthèses restent favorables : recommandations officielles polonaises avec une fenêtre de paramètres (630–670 nm en intrabuccal, 780–850 nm en extrabuccal, 2–6 J/cm²), méta-analyse pédiatrique positive qui contredit celle de 2024, revue de 13 essais en chimiothérapie. Le seul résultat défavorable vient d'un gel d'Arrabidaea chica qui cicatrise plus vite que le laser en greffe. Les études de vie réelle identifient les patients qui font une mucite sévère malgré la PBM : HPV positif, dénutrition, chimioradiothérapie, conditionnement au melphalan ou au méthotrexate.","l3":[{"h":"Voies d'administration","p":"Essai de référence intrabuccal contre extrabuccal en ORL (Supportive Care in Cancer, 58 patients) : pas de différence de grade (p = 0,69) et moins de dysphagie en extrabuccal. Essai d'association (Lasers Med Sci, 75 patients) : la combinaison surpasse l'intrabuccal seul dès la 2e semaine. La revue exploratoire de 2026 sur l'extrabuccal arrive juste avant ces données."},{"h":"Nouveaux dispositifs","p":"Gouttière intrabuccale à 43 points (6,6 % de mucites sévères chez 15 patients), appareil à domicile (60 % d'observance, mais 41 % de mucites sévères en fin de radiothérapie), LED (5 études, GRADE faible). Ce sont des preuves de faisabilité, pas encore d'efficacité comparative."},{"h":"Chimiothérapie et pédiatrie","p":"Préconditionnement avant la première cure : 80 à 87 % des patients sans mucite contre 7 % (deux publications issues probablement de la même cohorte syrienne). Méta-analyse pédiatrique de J Dent (5 essais, 177 enfants) positive. Essai iranien chez l'enfant sous MTX : incidence de 66,7 % à 6,7 % (avant-après) et thérapie photodynamique au vert d'indocyanine en curatif."},{"h":"Associations et comparateurs","p":"L-glutamine et acide hyaluronique ajoutés à la PBM : bénéfice sur l'échelle OMS seulement. Gel d'A. chica supérieur au laser pour la cicatrisation (5,2 contre 11,2 jours, essai ouvert). Dispositif Germinator équivalent au laser (sans bras témoin)."},{"h":"Implantation","p":"Acceptabilité élevée chez l'enfant et les parents au Royaume-Uni, freinée par la charge de travail des équipes. Au Brésil, les tribunaux reconnaissent la PBM comme un soin opposable aux assureurs (50 décisions)."},{"h":"Sécurité","p":"Signal sur l'épithélium de xénope à 660 nm (anomalies chez 30,6 % des têtards contre 3,8 %), sans équivalent clinique connu. Les revues mécanistiques confirment la modulation des cytokines (IL-6, TNF-α) et du stress oxydatif (nitrite salivaire, SOD)."}]},"2026":{"headline":"L'année de la consolidation : de grands essais et de nouveaux critères","l1":"En 2026, la plus grande méta-analyse (30 essais, 1 748 patients ORL) confirme une baisse de 54 % des mucites sévères, un essai multicentrique contre simulation valide un dispositif LED, et l'attention se porte sur la douleur, les opioïdes et la voie extrabuccale chez l'enfant.","l2":"Deux méta-analyses convergent : RR 0,46 pour la mucite sévère en ORL (avec un RR de 0,35 pour la douleur sévère) et RR 0,50 sur les essais récents, avec une certitude toujours faible. Les essais randomisés contre placebo ou simulation se multiplient : dispositif LED intrabuccal (85 patients, 12 centres américains, 36,8 % contre 57,1 % de mucites sévères), méthotrexate haute dose chez l'adulte (11,5 % contre 51,9 %, il suffit de traiter 2 patients), greffe (POMFITT, 0 % contre 26,6 %). Un essai en bouche divisée montre aussi un effet curatif (guérison 52,4 % contre 11,9 %).\n\nEn pédiatrie, deux essais brésiliens et une enquête de préférence placent la PBM extrabuccale au moins à égalité avec l'intrabuccale, avec un temps de séance divisé par dix et beaucoup moins d'inconfort. En France, une cohorte appariée de 280 patients montre que la PBM préventive réduit la morphine sans changer le grade de mucite : un argument pour mesurer la douleur et pas seulement le grade. Les revues parapluie et une étude sur le « spin » des résumés rappellent les limites méthodologiques du domaine.","l3":[{"h":"Synthèses quantitatives","p":"Méta-analyse à trois niveaux (Supportive Care in Cancer, mars) : mucite sévère RR 0,46 (0,29–0,71), douleur sévère RR 0,35 (0,23–0,53), débit salivaire DMS 0,75, xérostomie et qualité de vie non significatives ; certitude très faible à faible. Méta-analyse des essais 2020–2026 : RR 0,50 (0,35–0,73). Revue de 15 essais contre simulation chez l'adulte : bénéfice surtout en prévention intrabuccale. Revues parapluie (LLLT toutes indications ; complications ORL) : signal favorable sur la mucite, mais 90 % des revues de confiance faible ou critiquement faible."},{"h":"Essais majeurs","p":"LED intrabuccale contre simulation en IMRT (NCT03972527) : critère principal atteint (p = 0,046) avec un bénéfice sur le goût et la douleur. MTX-HD chez l'adulte : réduction relative du risque de 77,7 % et méthotrexate salivaire comme biomarqueur. POMFITT en greffe : mucite sévère évitée, sans bénéfice fonctionnel. Essai en bouche divisée (Radiotherapy & Oncology) : effet curatif sur la cicatrisation et la douleur dès la première semaine."},{"h":"Extrabuccal chez l'enfant","p":"Essai de 155 enfants : 30,5 % contre 41,1 % (NS), 30 s contre 6 min. Essai de 31 enfants randomisés par cure : avantage à l'extrabuccal (RR 1,84 en défaveur de l'intrabuccal). Préférence des parents : 65,6 % pour l'extrabuccal, 6,3 % d'inconfort contre 43,8 %. Un protocole d'essai de non-infériorité en ORL adulte (808 nm transcutané) est en cours."},{"h":"Douleur, opioïdes, odynophagie","p":"Cohorte française appariée : morphine 22,9 contre 37,4 mg/j en fin de radiothérapie et 10,3 contre 27,2 mg/j à un mois, avec des grades de mucite identiques (63 %). PBM haute puissance 940 nm sur l'odynophagie : baisse de 40 % de la douleur sur près de 4 jours. Vie réelle italienne : 10 séances ou plus réduisent odynophagie et dysphagie persistante, sans effet sur la survie."},{"h":"Méthodologie et implantation","p":"Spin dans 14 des 16 résumés d'essais analysés. Microbiome : hypothèse de recherche et non mécanisme établi. Royaume-Uni : l'adoption dépend de l'organisation locale, les LED réduisent les obstacles. Australie et Nouvelle-Zélande : PBM rarement utilisée, absente des recommandations nationales EviQ."}]},"2000–2009":{"headline":"Les essais fondateurs : de la greffe de moelle à la radiothérapie ORL","l1":"Entre 2000 et 2009, les premiers essais randomisés montrent que le laser basse énergie prévient la mucite, surtout en greffe de moelle (essai de Blood 2006, HR 0,07 pour la mucite sévère) et chez l'enfant sous chimiothérapie. Les recommandations MASCC/ISOO de 2006 le citent comme une piste prometteuse, sans encore le recommander.","l2":"Cette décennie pose les bases. En greffe de cellules souches, deux essais (Blood 2006 ; phase III en double aveugle, 70 patients) montrent une forte réduction de la mucite sévère, avec un effet qui dépend de la longueur d'onde : 650 nm efficace, 780 nm non. En pédiatrie, les résultats sont contrastés : un essai de 60 enfants est négatif, mais deux autres (dont un français) montrent 73 % de cures sans mucite contre 27 % sous placebo.\n\nEn radiothérapie ORL, le laser He-Ne réduit la douleur et le grade de mucite, et un essai brésilien établit qu'il faut au moins trois séances par semaine. Les équipes françaises publient deux études prospectives (81 à 83 % de succès). Les recommandations MASCC/ISOO de 2006, résumées dans le Bulletin du Cancer, constatent le peu de préventions prouvées et placent le laser parmi les pistes prometteuses.","l3":[{"h":"Greffe de cellules souches","p":"Essai de Blood 2006 : mucite de grade 3–4 quasi supprimée (HR 0,07), le laser devient le standard du centre. Phase III à 70 patients : 650 nm efficace sur la sévérité et la douleur, 780 nm non. La longueur d'onde compte."},{"h":"Pédiatrie","p":"Trois essais aux résultats discordants : négatif chez 60 enfants (2007), positif en prévention (73 % contre 27 % de cures sans mucite) et en curatif (1 enfant sur 9 avec lésions à J7 contre 9 sur 12). Ces divergences expliquent la prudence des recommandations pédiatriques suivantes."},{"h":"Radiothérapie ORL","p":"Laser He-Ne (Inde, 2006) : douleur et grade réduits. Brésil (2009) : trois séances par semaine stabilisent la mucite, une séance hebdomadaire ne suffit pas contre la douleur."},{"h":"Recommandations","p":"MASCC/ISOO 2006 : peu de préventions validées ; le laser est jugé prometteur mais pas encore recommandé, faute d'essais suffisants."}]},"2010–2019":{"headline":"La preuve se construit : méta-analyses, grands essais ORL et recommandations","l1":"Entre 2010 et 2019, la PBM passe du statut de piste prometteuse à celui de traitement recommandé. Les méta-analyses convergent (RR de 0,37 à 0,40 contre la mucite sévère), de grands essais ORL confirment l'effet (phase III brésilienne : 6,4 % contre 40,5 % de mucite de grade 3–4) et la MASCC/ISOO recommande la PBM préventive en 2019 dans trois situations.","l2":"La Cochrane de 2010 juge encore les preuves faibles. Les méta-analyses suivantes changent la donne : 11 essais en 2011 (effet surtout au-delà de 1 J), 18 essais en 2014 (risque de mucite sévère réduit de 63 %, douleur sévère de 74 %), 2019 en curatif (−62 % de mucite sévère à J7, guérison 4,2 jours plus tôt). Une méta-analyse en réseau de 57 essais classe laser + soins buccaux en tête des préventions de la mucite radio-induite.\n\nLes grands essais ORL sont positifs : Inde (121 et 221 patients, mucite sévère de 89 % à 29 %), Brésil (phase III, 94 patients, grade 3–4 divisé par six, coût de 4 961 USD par mucite sévère évitée, et même une meilleure survie sans progression à 41 mois). Deux essais restent négatifs : le laser à 2,5 J/cm² en radiochimiothérapie et l'essai français de phase III en curatif (2019). En greffe, les essais confirment l'effet (57 % sans mucite contre 5 % ; 18 % contre 61 % de mucite sévère).\n\nLa MASCC/ISOO passe d'une recommandation limitée à la greffe (2012–2014) à une recommandation en greffe, en radiothérapie ORL seule et en radiochimiothérapie ORL (2019), avec des protocoles précis. Les premières revues de sécurité tumorale (27 études) sont rassurantes, même si les données in vitro restent ambivalentes.","l3":[{"h":"Méta-analyses","p":"Cochrane 2010 : preuves faibles. 2011 : 11 ECR, effet dose-dépendant (> 1 J). 2014 : 18 ECR, 1 144 patients, RR 0,37 [0,20–0,67] contre la mucite sévère. 2017 : réseau de 57 ECR, laser + soins buccaux en tête (SUCRA 95,8 %). 2019 : curatif, RR 0,38 ; effet net chez l'adulte (RR 0,28), pas chez l'enfant (RR 0,90)."},{"h":"Radiothérapie ORL","p":"Phase III brésilienne (2013) : 6,4 % contre 40,5 % de grade 3–4 ; suivi à 41 mois : survie sans progression 62 % contre 40 %. Inde : 29 % contre 89 % de mucite sévère (121 patients), puis 221 patients en triple aveugle. Essais négatifs : 2,5 J/cm² (2012) et phase III française en curatif (54,8 % contre 43,9 %, 2019)."},{"h":"Greffe et pédiatrie","p":"Greffe : 57 % sans mucite contre 5 % (2011), 17,6 % contre 61,1 % de mucite sévère (2016) ; LED extrabuccale 670 nm (NASA) sur la douleur. Pédiatrie : essai italien laMPO (101 enfants) : guérison accélérée (93,7 % contre 72 % sous le grade 3 à J7)."},{"h":"Paramètres","p":"Consensus progressif : 630–685 nm, 10–100 mW, 2–4 J/cm², au moins 3 séances par semaine ; méta-analyse dosimétrique 2019 : efficace dans toute cette plage, 660 nm à 3,8 J/cm² un peu meilleur."},{"h":"Recommandations et sécurité","p":"MASCC/ISOO 2012–2014 : 650 nm en greffe, 632,8 nm suggéré en radiothérapie seule. 2019 : recommandation en greffe, radiothérapie ORL et radiochimiothérapie ORL. Revue de 27 études : pas de signal de sécurité tumorale ; in vitro, 7 études sur 13 montrent une inhibition et 6 une stimulation des cellules tumorales."}]},"2020–2023":{"headline":"Consolidation : coût-efficacité, extrabuccal et position de la WALT","l1":"De 2020 à 2023, l'efficacité préventive est considérée comme acquise (méta-analyses : RR de 0,28 à 0,40). La recherche se déplace vers le coût-efficacité, la PBM extrabuccale, la LED et l'association avec la cryothérapie. En 2022, la WALT étend la PBM à d'autres toxicités des traitements du cancer.","l2":"Les méta-analyses confirment et précisent : 30 études en 2020 (RR 0,40 contre la mucite sévère), ORL (RR 0,36, coût-efficace au Brésil), chimiothérapie avec analyse séquentielle concluante (RR 0,28, GRADE modéré), greffe (facteur de protection de 94 % avec 660 nm, 40 mW, 4 J/cm²). Une méta-analyse en réseau de 26 essais place l'association laser + cryothérapie en tête.\n\nLes essais testent la délivrance : PBM extrabuccale aussi efficace que l'intrabuccale en greffe, LED équivalente au laser chez l'enfant sous méthotrexate, association rouge + infrarouge meilleure que chaque longueur d'onde seule. Le coût par mucite sévère évitée est de 2 867 USD dans un essai brésilien et de 3 050 à 5 592 USD dans une revue. En pédiatrie, une revue de l'Archives of Disease in Childhood reste prudente en raison du risque de biais élevé.","l3":[{"h":"Méta-analyses","p":"2020 : 30 études, RR 0,40 [0,28–0,57]. ORL : RR 0,36. Chimiothérapie : RR 0,28, analyse séquentielle concluante. Greffe : DMS −1,34 et facteur de protection de 94 % avec les paramètres usuels. Réseau de 26 ECR : laser + cryothérapie en tête."},{"h":"Délivrance","p":"Extrabuccal contre intrabuccal en greffe : équivalents, séances plus courtes. LED contre laser à énergie égale chez l'enfant : 10 % contre 12,5 % de mucites. 660 + 810 nm combinés : meilleurs que chaque longueur d'onde seule."},{"h":"Économie","p":"2 867 USD par mucite sévère évitée et 2 757 USD par interruption de radiothérapie évitée (Brésil) ; revue de quatre études : 3 050 à 5 592 USD par mucite de grade 3–4 évitée."},{"h":"Recommandations","p":"WALT 2022 : reprend la MASCC/ISOO pour la mucite et propose des paramètres pour une quinzaine d'autres toxicités (radiodermite, xérostomie, neuropathie, lymphœdème…)."}]}},"global":{"headline":"2024 → 2026 : ce qui est acquis, ce qui bouge, ce qui manque","l1":"Sur trois ans, l'effet préventif de la PBM sur la mucite sévère reste remarquablement stable (RR de 0,45 à 0,54 dans les méta-analyses). Les recherches sont passées de la question de l'efficacité à celle de la délivrance (extrabuccal, LED, domicile) et de critères centrés sur le patient (douleur, opioïdes). La qualité méthodologique reste le point faible.","l2":"Acquis : la PBM préventive réduit environ de moitié la mucite sévère et d'environ deux tiers la douleur sévère, en ORL comme en chimiothérapie haute dose et en greffe. L'estimation ne bouge pas de 2024 (RR 0,45, 14 essais) à 2026 (RR 0,46, 30 essais), alors que le nombre de patients a doublé. Elle est désormais confirmée par des essais multicentriques contre simulation. Le moment compte (préventif plutôt que curatif) et la fréquence aussi (quotidien plutôt qu'espacé).\n\nCe qui bouge : la voie extrabuccale passe d'une option peu étayée (revue exploratoire) à une alternative validée en essai randomisé, chez l'adulte ORL en 2025 puis chez l'enfant en 2026. Les critères de jugement s'élargissent à la douleur, aux opioïdes, au goût, à la déglutition et aux coûts. La pédiatrie passe d'une méta-analyse négative (2024) à une méta-analyse positive (2025) et à des essais spécifiques (2026). Ce qui manque : des revues de qualité (la revue Cochrane est attendue), une dosimétrie standardisée, des données de sécurité oncologique à long terme au-delà des cohortes rassurantes, et des comparaisons directes avec les autres options (cryothérapie, topiques).","l3":[{"h":"0. Le temps long : 2000 → 2023","p":"Depuis 2000, la PBM contre la mucite a suivi une trajectoire nette : essais fondateurs en greffe et en pédiatrie (2000–2009), accumulation de méta-analyses convergentes et recommandation MASCC/ISOO en 2019 (2010–2019), puis consolidation (coût-efficacité, extrabuccal, WALT 2022). L'effet préventif est remarquablement stable dans le temps : un risque de mucite sévère réduit d'environ 60 % (RR de 0,37 en 2014 à 0,46 en 2026). Les essais négatifs portent surtout sur des doses faibles ou un usage curatif tardif."},{"h":"1. Un effet stable malgré l'accumulation des données","p":"Les quatre estimations poolées sur la mucite (2024 : RR 0,45 et RR 0,54 ; 2026 : RR 0,46 et RR 0,50) se recouvrent largement. Quand un effet ne s'érode pas alors que les essais s'accumulent, c'est un argument contre un simple biais de publication. La seule méta-analyse discordante, pédiatrique (2024, RR 0,99), reposait sur très peu d'essais et a été contredite en 2025."},{"h":"2. Une qualité méthodologique qui ne progresse pas assez","p":"Les revues parapluie de 2024 (71 % de revues critiquement faibles) et de 2026 (60 %) font le même constat, et l'étude de 2026 trouve du spin dans 14 résumés d'essais sur 16. La certitude GRADE de la plus grande méta-analyse reste très faible à faible. Les essais de 2026 (LED multicentrique en double aveugle, MTX-HD en double aveugle) montrent cependant une montée en qualité des études primaires."},{"h":"3. De la question « est-ce efficace ? » à la question « comment le délivrer ? »","p":"2024 : fréquence (quotidien plutôt qu'espacé) et moment (préventif plutôt que curatif). 2025 : extrabuccal équivalent en ORL, association des deux voies, gouttières, domicile. 2026 : extrabuccal chez l'enfant, LED autonome validée, 10 séances au moins en vie réelle. La logistique, c'est-à-dire le temps de séance, le personnel et l'inconfort, est devenue un objet de recherche à part entière."},{"h":"4. Des critères centrés sur le patient","p":"La cohorte française de 2026 illustre un tournant : moins de morphine sans changement du grade de mucite. La douleur, l'odynophagie, le goût, la déglutition, la nutrition et les coûts deviennent des critères principaux. Pour la pratique, il faut suivre la consommation d'antalgiques et la qualité de vie, pas seulement le grade OMS."},{"h":"5. La sécurité oncologique, une vigilance qui reste nécessaire","p":"Les signaux défavorables viennent tous de modèles précliniques (mélanome murin à 808 nm en 2024, xénope en 2025, lignées tumorales). Les données cliniques sont rassurantes (aucune surmortalité en 2024, aucun effet sur la survie sans progression ni la survie globale en 2026) mais rétrospectives. La position francophone (Bulletin du Cancer 2024) reste d'actualité : doses validées, information et consentement près d'une tumeur."},{"h":"6. Implantation : les preuves ne suffisent pas","p":"Royaume-Uni (2025–2026) : acceptable mais peu déployée, faute d'organisation. Australie et Nouvelle-Zélande : rarement utilisée (coût, recommandations nationales). Brésil : opposable par voie judiciaire. États-Unis (pédiatrie) : faisable avec une infirmière dédiée et rentable. Les LED et l'extrabuccal semblent lever une partie des obstacles."}],"table":{"cols":["2000–2009","2010–2019","2020–2023","2024","2025","2026"],"rows":[{"label":"Question dominante","cells":["Est-ce que ça marche ?","Avec quelle force de preuve ?","À quel coût, par quelle voie ?","Est-ce efficace ? Avec quelle qualité de preuve ?","Comment la délivrer (voie, dispositif) ?","Confirmer en multicentrique, élargir les critères"]},{"label":"Méta-analyse phare","cells":["—","18 ECR, RR 0,37 (2014) ; réseau 57 ECR (2017)","30 études, RR 0,40 ; chimio RR 0,28","Head & Neck : 14 ECR, RR 0,45","Pédiatrie (J Dent) : 5 ECR, bénéfice significatif","Supportive Care in Cancer : 30 ECR, RR 0,46"]},{"label":"Essai phare","cells":["Blood 2006 : greffe, HR 0,07","Phase III Brésil : 6,4 % contre 40,5 %","Rouge + infrarouge > chaque longueur d'onde","Quotidien contre un jour sur trois (n = 16)","Intra contre extrabuccal ORL (n = 58)","LED contre simulation, 12 centres (n = 85)"]},{"label":"Pédiatrie","cells":["3 ECR discordants","laMPO (n = 101) positif ; méta-analyse 2019 : RR 0,90","LED = laser ; revue prudente (biais)","Méta-analyse négative ; ECR LAM positif","Méta-analyse positive ; acceptabilité","Extrabuccal ≥ intrabuccal (n = 155 et n = 31)"]},{"label":"Douleur","cells":["He-Ne : douleur ↓","Douleur sévère −74 % (2014)","Pas d'effet démontré en ORL (2020)","Haute puissance, effet immédiat","Curatif 810 nm, douleur ↓","Morphine ↓ (cohorte FR, n = 280) ; odynophagie"]},{"label":"Sécurité","cells":["—","27 études : pas de signal ; in vitro ambivalent","WALT 2022","Signal 808 nm (mélanome murin) ; Bulletin du Cancer","Signal Xenopus","Pas d'effet sur la survie (vie réelle)"]},{"label":"Qualité des preuves","cells":["Petits essais","Cochrane 2010 : faible → MASCC 2019","GRADE modéré (chimio)","Parapluie : 71 % critiquement faibles","GRADE faible (LED)","Parapluie : 60 % critiquement faibles ; spin"]}]}}},"musculo-squelettique":{},"neuropathie-peripherique":{"years":{"2024":{"headline":"Beaucoup de compressions nerveuses, peu de neuropathies systémiques","l1":"En 2024, les essais portent surtout sur le canal carpien et le nerf ulnaire, avec des bénéfices surtout à court terme ; les neuropathies diabétiques et chimio-induites n'ont que des petits essais et beaucoup d'études animales.","l2":"Les compressions nerveuses dominent : deux essais sur le nerf ulnaire (bénéfice à court terme, qui s'estompe à 3 mois), trois sur le canal carpien, dont un négatif (le laser n'ajoute rien aux exercices), et une méta-analyse favorable au laser haute intensité à court terme. Dans la neuropathie diabétique, un essai iranien Tecar + laser (publié deux fois) et une chaussure laser sans témoin restent des preuves faibles.\n\nLa recherche fondamentale est active : six études chez le rat montrent un effet antalgique (constriction du sciatique, ligature spinale, diabète induit), sans toujours protéger la structure du nerf. Un travail de modélisation montre que c'est la dose de lumière au niveau du nerf, et non la puissance de l'appareil, qui sépare les protocoles efficaces des autres. La synthèse du Bulletin du Cancer juge le niveau de preuve encore faible pour la neuropathie chimio-induite.","l3":[{"h":"Compressions nerveuses","p":"Nerf ulnaire au coude (68 patients, double aveugle) : douleur et fonction améliorées à 3 mois, sans effet électrophysiologique. Canal cubital (64 patients) : avantage à 3 semaines, équivalence à 3 mois. Canal carpien : laser équivalent aux ondes de choc, sans apport en plus des exercices, et méta-analyse haute intensité (308 patients) favorable à court terme."},{"h":"Neuropathie diabétique","p":"Tecar + laser (45 patients, double aveugle, deux publications) : l'association est la plus durable ; le laser seul fait moins bien. Chaussure laser (60 patients, sans témoin) : douleur et pressions plantaires réduites. Protocole d'une méta-analyse dédiée."},{"h":"Préclinique et dosimétrie","p":"Effet antalgique reproductible chez le rat à 850–904 nm, mécanismes inflammatoires (RAGE/NF-κB, IL-1β, NGF), régénération après écrasement (Nd:YAG pulsé). La modélisation de l'irradiance au nerf donne un cadre pour choisir la dose selon la profondeur."},{"h":"Neuropathie chimio-induite","p":"Pas d'essai clinique spécifique en 2024 ; la synthèse française classe la PBM comme encore peu étayée dans cette indication."}]},"2025":{"headline":"Le premier grand essai dans la neuropathie diabétique et les premières méta-analyses","l1":"En 2025, un essai de 200 diabétiques montre un effet de la PBM sur la douleur et les biomarqueurs nerveux. Les méta-analyses sur le canal carpien et les neuropathies orofaciales sont favorables, et un consensus international (JAAD) retient la neuropathie périphérique comme indication.","l2":"La neuropathie diabétique gagne en preuves : essai indien de 200 patients contre simulation (laser He-Ne sur les pieds, douleur, sensibilité vibratoire, qualité de vie, NSE et CGRP améliorés), essai chinois à 10,6 μm favorable, et essai à trois bras au résultat modeste. Une revue dosimétrique propose une fenêtre : 630–670 nm ou 808–904 nm, 3 à 10 J/cm², au moins 12 séances.\n\nLes synthèses se multiplient. Dans le canal carpien, la méta-analyse en réseau (49 essais) place le laser parmi les traitements efficaces mais derrière la thérapie manuelle ; une autre méta-analyse ne trouve d'effet que sur la fonction ; le laser haute intensité est confirmé. Dans les neuropathies orofaciales, 18 essais montrent une baisse de 3,5 points de la douleur. Côté chimio-induite, une étude brésilienne sans témoin montre de meilleurs symptômes, équilibre et marche.","l3":[{"h":"Neuropathie diabétique","p":"Essai de 200 patients (Diabetes Res Clin Pract) : le plus solide de la période. Essai 10,6 μm (68 patients, double aveugle) : symptômes et qualité de vie améliorés, pas la conduction. Essai laser contre ultrasons (55 patients) : effet sur la qualité de vie, pas sur le score de symptômes."},{"h":"Canal carpien et compressions","p":"Méta-analyse en réseau : laser DMS −1,45 contre contrôle, mais thérapie manuelle et glucosé en tête. Méta-analyse PBM basse intensité (13 essais) : fonction améliorée, pas la douleur. Méta-analyse haute intensité (9 essais) : douleur, handicap et conduction améliorés, certitude modérée à faible."},{"h":"Neuropathie chimio-induite","p":"Étude brésilienne (47 patients, 630/850 nm) : DN-4, équilibre et marche améliorés, sans témoin. Revue de 26 essais d'exercice et de kinésithérapie : la PBM est l'une des modalités utiles, à combiner avec l'exercice."},{"h":"Consensus et orofacial","p":"Consensus Delphi du JAAD (21 experts) : PBM sûre et efficace dans la neuropathie périphérique. Revue maxillo-faciale (18 essais, 1 220 patients) : douleur −3,5 et récupération sensitive plus rapide."}]},"2026":{"headline":"Des essais contre simulation et une première recommandation","l1":"En 2026, un essai multicentrique américain contre simulation valide un laser à domicile dans la neuropathie diabétique douloureuse (72,7 % de répondeurs contre 32,3 %). Le premier essai belge dans la neuropathie chimio-induite est encourageant, et la WALT publie des recommandations pour les douleurs neuropathiques orofaciales.","l2":"La neuropathie diabétique douloureuse dispose de son essai de référence : dispositif rouge + violet utilisé à domicile, quatre centres, double aveugle, 40 points de répondeurs en plus qu'avec la simulation à 3 semaines. Un pilote brésilien avec ILIB ne montre pas de supériorité sur la simulation. Dans la neuropathie chimio-induite, l'essai NEUROLIGHT (60 patients) améliore le score de neuropathie, la marche et la douleur, mieux à 6 J/cm², sans groupe placebo.\n\nLes compressions nerveuses passent au laser haute intensité : canal carpien (supérieur au laser basse intensité), méralgie paresthésique (double aveugle contre simulation) et canal cubital après brûlure (supérieur aux ondes de choc). La WALT recommande la PBM dans le syndrome de la bouche brûlante et émet un avis favorable pour les névralgies trigéminale et post-zostérienne. La recherche animale se tourne vers la neuropathie chimio-induite (paclitaxel, cisplatine) et la myéline.","l3":[{"h":"Neuropathie diabétique","p":"Essai multicentrique NCT05291975 (64 patients) : 72,7 % contre 32,3 % de répondeurs, EVA −33,4 contre −20,0, effet maintenu à 7 semaines. Pilote PBM ± ILIB (26 patients) : douleur en baisse dans le temps, sans interaction avec le groupe."},{"h":"Neuropathie chimio-induite","p":"NEUROLIGHT (Belgique, 60 patients, 6 contre 8 J/cm²) : mTNS, 6MWT et douleur améliorés, qualité de vie inchangée, sans bras placebo. Préclinique : PBM 808 nm chez la souris sous paclitaxel (fibres nerveuses restaurées), PBM 660 nm sur cellules exposées au cisplatine (voie AMPK)."},{"h":"Compressions nerveuses","p":"Canal carpien subaigu (69 patients) : haute intensité supérieure à basse intensité, toutes deux meilleures que la simulation. Méralgie paresthésique (62 patients, 1 064 nm) : douleur, fonction et conduction améliorées à 12 semaines. Canal cubital post-brûlure (75 patients) : haute intensité supérieure aux ondes de choc. Laser He-Ne après acupotomie : aussi efficace que les corticoïdes, sans hyperglycémie."},{"h":"Recommandations","p":"WALT 2026 : bouche brûlante (niveau I), névralgie trigéminale idiopathique et post-zostérienne (niveau II, avis d'experts). Revue de 14 essais sur la douleur chronique : effets les plus nets dans la fibromyalgie et la neuropathie."}]},"2000–2009":{"headline":"Le canal carpien, premier terrain d'essai","l1":"Entre 2000 et 2009, la PBM dans les neuropathies périphériques se résume presque au canal carpien, avec des essais contradictoires : plusieurs sont positifs contre placebo, d'autres négatifs, et les ultrasons font parfois mieux. Le premier essai dans la neuropathie diabétique (Diabetes Care 2004) est négatif.","l2":"Une dizaine d'essais randomisés étudient le laser dans le canal carpien. Les résultats sont partagés : amélioration de la douleur, de la force et des latences contre placebo dans plusieurs essais (2007–2009), mais absence d'effet dans d'autres (15 et 81 patients) et supériorité des ultrasons dans un essai de 2004. L'association laser + attelle fait mieux que l'attelle seule chez 50 femmes. Une revue de 2007 (33 essais) juge les preuves limitées ou contradictoires pour le laser, fortes pour les corticoïdes.\n\nHors canal carpien, deux essais ouvrent des pistes : la neuropathie diabétique douloureuse (Diabetes Care 2004 : tendance non significative, −1 point) et les lésions nerveuses périphériques anciennes (780 nm, amélioration motrice sur 6 mois en double aveugle).","l3":[{"h":"Canal carpien","p":"Essais positifs : 2007 (polyarthrite), 2008 (latences et force), 2008 (ligament transverse), 2009 (laser + attelle > ultrasons + attelle). Négatifs : 860 nm (n = 15), 81 patients (seule la force s'améliore), ultrasons > laser (2004). Revue de 2007 : preuves limitées."},{"h":"Neuropathie diabétique","p":"Diabetes Care 2004 : −1 point de douleur, non significatif, sans effet sur la conduction ni la sensibilité."},{"h":"Lésions nerveuses","p":"Lésions incomplètes anciennes : 780 nm, amélioration motrice sur 6 mois contre placebo en double aveugle. Une base pour les essais de régénération nerveuse."}]},"2010–2019":{"headline":"Méta-analyses discordantes dans le canal carpien, premier essai positif dans la neuropathie chimio-induite","l1":"Entre 2010 et 2019, les méta-analyses du canal carpien divergent : effet sur la force, la douleur et le potentiel sensitif à 12 semaines pour l'une, pas mieux que le placebo pour l'autre. Le fait marquant de la décennie est le premier essai contre simulation dans la neuropathie chimio-induite (2016), avec 53 % de réduction du score à 8 semaines.","l2":"Dans le canal carpien, les essais s'accumulent : laser haute intensité supérieur à la TENS, laser + attelle supérieur à l'attelle seule, laser-acupuncture efficace, mais aussi essais négatifs et supériorité de la manipulation fasciale. Les synthèses de 2016 à 2018 concluent à un effet à court terme, surtout sur la force, dont la portée est discutée (un essai pèse plus de 95 % d'une méta-analyse). Les paramètres les plus efficaces semblent se situer entre 780 et 860 nm, à 9–11 J/cm².\n\nLa neuropathie chimio-induite apparaît avec l'essai de Gynecologic Oncology (2016, −32 % puis −53 % du score de neuropathie), et une revue de 2018 classe la PBM avec la duloxétine parmi les deux options de bénéfice modéré. Dans la neuropathie diabétique, une revue de six études et un essai pilote chez le sujet âgé sont favorables. En chirurgie maxillo-faciale, le laser améliore la récupération sensitive du nerf alvéolaire inférieur.","l3":[{"h":"Canal carpien","p":"Méta-analyse 2016 (7 ECR) : force, douleur et potentiel sensitif à 12 semaines, mais un essai domine. Méta-analyse 2017 : seule la force s'améliore. Revue 2017 : 780–860 nm à 9–11 J/cm². Haute intensité > TENS (2013). Laser-acupuncture positive (2019)."},{"h":"Neuropathie chimio-induite","p":"Essai contre simulation (2016) : −32 % du score à 4 semaines, −53 % à 8 semaines. Revue 2018 (35 études) : PBM et duloxétine, bénéfice modéré. Revue de sécurité 2019 : pas de signal tumoral."},{"h":"Neuropathie diabétique","p":"Essai iranien mitigé (2013) ; laser profond chez l'âgé : douleur et mobilité améliorées (2019) ; revue de six études favorable ; laser et LED améliorent les signes neuropathiques des ulcères."},{"h":"Autres","p":"Nerf ulnaire au coude : laser ≈ ultrasons. Nerf alvéolaire inférieur après ostéotomie : six études favorables. Douleur neuropathique (revue de 14 articles, surtout animaux) : effet meilleur au-delà de 70 mW."}]},"2020–2023":{"headline":"Diversification : haute intensité, chirurgie nerveuse et prévention de la neuropathie chimio-induite","l1":"De 2020 à 2023, la recherche se diversifie : laser haute intensité dans le canal carpien, PBM après chirurgie nerveuse (plexus brachial, libération du carpe), prévention de la neuropathie chimio-induite (NEUROLASER) et neuropathie diabétique. Les synthèses restent prudentes, mais la WALT 2022 propose des paramètres pour la neuropathie chimio-induite.","l2":"Dans le canal carpien, une méta-analyse en réseau juge l'ajout du laser à l'attelle non cliniquement significatif (−0,5 cm), et une revue parapluie de 17 revues reste non concluante. Le laser égale l'infiltration de corticoïde à 6 mois, et le laser haute intensité fait mieux que le laser basse énergie. Après libération chirurgicale, la PBM accélère la récupération ; après neurotisation du plexus brachial, elle accélère la réinnervation.\n\nPour la neuropathie chimio-induite, l'essai pilote NEUROLASER (cancer du sein) montre une stabilisation des symptômes sous PBM préventive, alors qu'un essai de phase II chez des survivants donne des taux de réponse proches (48 % contre 53 %). Dans la neuropathie diabétique, l'ILIB modifiée et une revue de huit études sont favorables (douleur, conduction, pressions plantaires).","l3":[{"h":"Canal carpien","p":"Réseau de 6 ECR (2020) : −0,5 cm, non recommandé. Parapluie (2023) : non concluant. Laser ≈ corticoïde à 6 mois. Haute intensité 1,6 W > basse énergie. Méta-analyse 2023 : −1,3 point contre simulation."},{"h":"Chirurgie nerveuse","p":"Plexus brachial (Oberlin) : réinnervation et force à 3 mois. Après libération du carpe : fonction, douleur et force de pince améliorées."},{"h":"Neuropathie chimio-induite","p":"NEUROLASER : symptômes stables sous PBM contre aggravation sous placebo. Phase II : 48 % contre 53 % de répondeurs à 6 semaines, maintien meilleur à 12 semaines. WALT 2022 : paramètres proposés."},{"h":"Diabète et orofacial","p":"ILIB modifiée (660 nm, 30 séances) favorable ; revue de 8 études : douleur, conduction et pressions plantaires. Orofacial (13 études) : névralgie trigéminale et bouche brûlante soulagées."}]}},"global":{"headline":"2024 → 2026 : des compressions nerveuses vers la neuropathie diabétique et chimio-induite","l1":"En trois ans, la PBM dans les neuropathies périphériques passe de petits essais sur le canal carpien à de vrais essais contre simulation dans la neuropathie diabétique douloureuse. La neuropathie chimio-induite reste le parent pauvre, malgré des données animales et un premier essai encourageants.","l2":"Acquis : dans les neuropathies de compression (canal carpien, nerf ulnaire, méralgie), la PBM, surtout à haute intensité, améliore la douleur et la fonction à court terme, en complément de l'attelle et des exercices ; l'effet à moyen terme est moins net, et un essai montre qu'elle n'ajoute rien à des exercices bien conduits. Dans la neuropathie diabétique douloureuse, deux essais contre simulation solides (200 patients en 2025, multicentrique en 2026) confirment un soulagement de court terme.\n\nCe qui manque : un essai contre simulation dans la neuropathie chimio-induite (NEUROLIGHT compare deux doses), des suivis au-delà de 3 mois, une dosimétrie raisonnée selon la profondeur du nerf, et la méta-analyse annoncée en 2024 dans la neuropathie diabétique. Les recommandations apparaissent (consensus JAAD 2025, WALT 2026 pour l'orofacial) mais restent portées par des sociétés de PBM.","l3":[{"h":"0. Le temps long : 2000 → 2023","p":"Pendant vingt ans, la PBM dans les neuropathies périphériques a été dominée par le canal carpien, avec des résultats constamment partagés : effet à court terme sur la force et parfois la douleur, sans bénéfice clinique net à moyen terme dans les synthèses. Les deux tournants sont l'essai de 2016 dans la neuropathie chimio-induite et l'essor, après 2019, des essais dans la neuropathie diabétique et après chirurgie nerveuse."},{"h":"1. Les compressions nerveuses, terrain le plus étudié","p":"Le canal carpien concentre la recherche (analyse bibliométrique 2026). Les méta-analyses divergent sur la douleur (réseau : DMS −1,45 ; autre méta-analyse : non significatif) mais s'accordent sur la fonction. Le laser haute intensité s'impose entre 2024 et 2026, avec trois essais en 2026 qui le donnent supérieur au basse intensité ou aux ondes de choc."},{"h":"2. La neuropathie diabétique, l'indication qui progresse le plus","p":"En 2024, il n'y avait que des petits essais combinés (Tecar) ou sans témoin. En 2025 paraît un essai de 200 patients contre simulation, avec biomarqueurs. En 2026, un essai multicentrique en double aveugle teste un dispositif à domicile. L'effet porte sur la douleur et la qualité de vie plus que sur la conduction nerveuse."},{"h":"3. La neuropathie chimio-induite, une preuve encore à construire","p":"Bulletin du Cancer 2024 : preuve faible. 2025 : étude avant-après (équilibre, marche). 2026 : NEUROLIGHT, sans placebo, et deux études précliniques solides (paclitaxel, cisplatine). La question de la prévention pendant la chimiothérapie reste ouverte ; c'est la priorité de recherche pour les soins de support."},{"h":"4. Mécanismes : antalgie avant réparation","p":"Les modèles animaux montrent un effet antalgique constant, mais pas toujours une protection structurelle du nerf (2024). Les études de 2026 retrouvent des effets sur le NGF, la myéline et les mitochondries. L'antalgie passerait en partie par un blocage des petites fibres, selon la dose au nerf."},{"h":"5. Les paramètres","p":"Fenêtre proposée pour la neuropathie diabétique : 630–670 nm ou 808–904 nm, 3–10 J/cm², 45–100 mW, au moins 12 séances. NEUROLIGHT suggère une fluence modérée (6 J/cm²) plus antalgique. Le laser haute intensité (1 064 nm) gagne du terrain dans les compressions."}],"table":{"cols":["2000–2009","2010–2019","2020–2023","2024","2025","2026"],"rows":[{"label":"Question dominante","cells":["Canal carpien : est-ce efficace ?","Méta-analyses du canal carpien","Diversification des indications","Compressions nerveuses, mécanismes","Neuropathie diabétique, méta-analyses","Essais contre simulation, recommandations"]},{"label":"Essai phare","cells":["Diabetes Care 2004 (négatif)","Neuropathie chimio-induite contre simulation (2016)","NEUROLASER ; plexus brachial","Nerf ulnaire, double aveugle (n = 68)","Neuropathie diabétique He-Ne (n = 200)","Laser à domicile multicentrique (n = 64)"]},{"label":"Synthèse phare","cells":["Revue 2007 : preuves limitées","Méta-analyses 2016–2017 discordantes","Parapluie canal carpien : non concluant","Haute intensité canal carpien (308 patients)","Réseau canal carpien (49 ECR) ; orofacial (18 ECR)","WALT orofacial ; douleur chronique (14 ECR)"]},{"label":"Neuropathie chimio-induite","cells":["—","−53 % à 8 semaines ; revue 2018","Prévention (NEUROLASER) ; phase II mitigée","Preuve faible (Bulletin du Cancer)","Avant-après, équilibre et marche (n = 47)","NEUROLIGHT (n = 60) ; préclinique"]},{"label":"Haute intensité","cells":["—","Haute intensité > TENS (2013)","1,6 W > basse énergie (2020)","Méta-analyse canal carpien","Méta-analyse canal carpien","3 essais : carpien, méralgie, cubital"]}]}}}},"n_chunks":40};
